import '@servicenow/sdk/global'
import { StringColumn, BooleanColumn } from '@servicenow/sdk/core'
import { Flow, wfa, Subflow } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// -----------------------------------------------------------------------------
// Two tiny Subflows that we will call from the main Flow
// -----------------------------------------------------------------------------
export const firstSub = Subflow({
    $id: Now.ID['sub_one'],
    name: 'Sub One',
    runAs: 'system',
    runWithRoles: [],
    flowPriority: 'LOW',
    inputs: {
        in1: StringColumn({ label: 'In-1', mandatory: true }),
    },
    outputs: {
        out1: BooleanColumn({ label: 'Out-1', mandatory: true }),
    },
})

export const secondSub = Subflow({
    $id: Now.ID['sub_two'],
    name: 'Sub Two',
    runAs: 'system',
    runWithRoles: [],
    flowPriority: 'LOW',
    inputs: {
        message: StringColumn({ label: 'Message', mandatory: true }),
    },
    outputs: {
        ok: BooleanColumn({ label: 'OK', mandatory: true }),
    },
})

// -----------------------------------------------------------------------------
// Main Flow that calls both subflows
// -----------------------------------------------------------------------------
Flow(
    {
        $id: Now.ID['flow_with_subflows'],
        name: 'Flow - Calls Two Subflows',
        description: 'Demonstrates multiple SubflowInstance records',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trg_subflow_example'] },
        {
            table: 'task',
            condition: 'active=true',
            run_on_extended: 'false',
            run_flow_in: 'foreground',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_trigger) => {
        wfa.subflow(
            firstSub,
            { $id: Now.ID['sub_one_instance'] },
            {
                in1: 'abc',
            }
        )

        wfa.subflow(
            secondSub,
            { $id: Now.ID['sub_two_instance'] },
            {
                message: 'xyz',
            }
        )
    }
)
